fd_set rfds;
struct timespec ts;
sigset_t mask;
int res;

FD_ZERO(&rfds);
FD_SET(STDIN_FILENO, &rfds);

ts.tv_sec = 5;
ts.tv_nsec = 0; // 5 second timeout

sigemptyset(&mask);
sigaddset(&mask, SIGINT);

res = pselect(STDIN_FILENO + 1,
             &rfds, NULL, NULL,
             &ts, &mask);

// Check FD_ISSET() if res > 0
